def cc(g,c):
    seen=set(); out=[]
    for r in range(len(g)):
        for x in range(len(g[0])):
            if g[r][x]==c and (r,x) not in seen:
                st=[(r,x)]; seen.add((r,x)); cells=[]
                while st:
                    y,yy=st.pop()
                    cells.append((y,yy))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            p=(y+dy,yy+dx)
                            if 0<=p[0]<len(g) and 0<=p[1]<len(g[0]) and g[p[0]][p[1]]==c and p not in seen:
                                seen.add(p); st.append(p)
                out.append(cells)
    return out
def solve(g,bg=None):
    from collections import Counter
    cnt=Counter(sum(g,[]))
    if bg is None: bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in g]
    for col in set(sum(g,[])):
        if col==bg: continue
        for c in cc(g,col):
            rs=[r for r,_ in c]; xs=[x for _,x in c]
            rmin,rmax,xmin,xmax=min(rs),max(rs),min(xs),max(xs)
            h,w=rmax-rmin+1,xmax-xmin+1
            if not(h>=2 and w>=2): continue
            ring={(r,x) for r in (rmin,rmax) for x in range(xmin,xmax+1)} | {(r,x) for x in (xmin,xmax) for r in range(rmin,rmax+1)}
            if set(c)==ring:
                for y,x in c: out[y][x]=3
    return out
